parameters.jsCode:
// Nó "Monta a busca": acha no GLPI a categoria de phishing e o grupo da Segurança da Informação
// e monta a busca dos chamados AINDA ABERTOS que têm as duas coisas (categoria + grupo atribuído).
// Chamado de outra categoria não entra: se o usuário escolheu errado, o analista corrige a
// categoria no GLPI e o chamado entra na próxima rodada.
const cfg = $('Configuração').first().json;
const lista = (nome) => {
  const corpo = $(nome).first().json.body;
  return Array.isArray(corpo) ? corpo : [];
};
const acha = (itens, campo, valor, oque) => {
  const achado = itens.find((i) => String(i[campo] ?? '').trim() === valor);
  if (!achado) throw new Error(`Não achei no GLPI ${oque} "${valor}". Rode antes: bash glpi/preparar-glpi.sh`);
  return Number(achado.id);
};
const categoriaId = acha(lista('Lê as categorias'), 'completename', cfg.categoria, 'a categoria');
const grupoId = acha(lista('Lê os grupos'), 'name', cfg.grupo, 'o grupo');

// Campos da busca do GLPI: 2 = número, 7 = categoria, 8 = grupo técnico, 12 = status, 15 = abertura.
const parametros = [
  ['criteria[0][field]', 7], ['criteria[0][searchtype]', 'equals'], ['criteria[0][value]', categoriaId],
  ['criteria[1][link]', 'AND'], ['criteria[1][field]', 8], ['criteria[1][searchtype]', 'equals'], ['criteria[1][value]', grupoId],
  ['criteria[2][link]', 'AND'], ['criteria[2][field]', 12], ['criteria[2][searchtype]', 'equals'], ['criteria[2][value]', 'notold'],
  ['forcedisplay[0]', 2], ['forcedisplay[1]', 15], ['sort', 15], ['order', 'ASC'], ['range', '0-19'],
];
return [{ json: {
  categoria_id: categoriaId,
  grupo_id: grupoId,
  consulta: parametros.map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(String(v))).join('&'),
} }];

// Nó "Lista os candidatos": chamados abertos da busca, do mais antigo para o mais novo.
// Nenhum chamado: devolve lista vazia e a execução para aqui (sem gastar nada).
const corpo = $input.first().json.body ?? {};
const linhas = Array.isArray(corpo.data) ? corpo.data : [];
const prefixo = $('Configuração').first().json.prefixoRedis;
return linhas
  .map((l) => Number(l['2'] ?? l[2]))
  .filter((id) => Number.isInteger(id) && id > 0)
  .slice(0, 10)
  .map((id) => ({ json: { chamado_id: id, chave_reserva: `${prefixo}relato:${id}` } }));

// Nó "Escolhe o próximo": pega o primeiro chamado que ainda não foi analisado.
// Um chamado por execução: o fluxo roda a cada 2 minutos, e assim a cota do VirusTotal
// (4 consultas por minuto) e a da IA nunca estouram, mesmo com muitos relatos de uma vez.
const candidatos = $('Lista os candidatos').all();
const prefixo = $('Configuração').first().json.prefixoRedis;
const hoje = new Date().toISOString().slice(0, 10);
const indice = $input.all().findIndex((item) => item.json.reserva === null || item.json.reserva === undefined || item.json.reserva === '');
if (indice < 0) return [{ json: { nenhum: true } }]; // todos já analisados: só fecha a sessão
const c = candidatos[indice].json;
return [{ json: { ...c, chave_cota: `${prefixo}cota:${hoje}` } }];

// Nó "Lista os anexos": documentos ligados ao chamado (o .eml do e-mail suspeito, prints, PDFs...).
// Sem anexo: devolve um item marcador, e o fluxo segue direto para a extração das evidências.
const corpo = $input.first().json.body;
const ligacoes = Array.isArray(corpo) ? corpo : [];
const maximo = Number($('Configuração').first().json.maxAnexos) || 4;
const ids = [...new Set(ligacoes.map((l) => Number(l.documents_id)).filter((id) => id > 0))].slice(0, maximo);
if (!ids.length) return [{ json: { sem_anexo: true } }];
return ids.map((id) => ({ json: { documento_id: id } }));

// Nó "Escolhe o que baixar": só o que for e-mail ou texto é baixado e lido (.eml, .msg, .txt, .html).
// Dos outros anexos (PDF, Office, executáveis, imagens) ficam o nome e o hash SHA-1 que o GLPI já
// calcula: o arquivo suspeito NUNCA é aberto pelo fluxo.
const docs = $input.all();
return docs.map((item, i) => {
  const d = item.json.body ?? {};
  const nome = String(d.filename ?? d.name ?? '');
  const mime = String(d.mime ?? '').toLowerCase();
  const ext = nome.toLowerCase().split('.').pop();
  const baixar = ['eml', 'msg', 'txt', 'htm', 'html'].includes(ext) || mime === 'message/rfc822' || mime === 'application/vnd.ms-outlook';
  return { json: {
    documento_id: Number(d.id ?? $('Lista os anexos').all()[i]?.json.documento_id),
    nome,
    mime,
    sha1: /^[0-9a-f]{40}$/i.test(String(d.sha1sum ?? '')) ? String(d.sha1sum).toLowerCase() : '',
    baixar,
  }, pairedItem: i };
});

// ---- Biblioteca: endereços IP que não são públicos (privados, locais, reservados, documentação) ----
// Usada para ignorar IPs internos nos cabeçalhos Received e nos links (não são indicadores de ataque).

// Converte "a.b.c.d" em número (0 a 2^32-1). Devolve null se não for IPv4 válido.
function ipv4ParaNumero(ip) {
  const partes = String(ip).split('.');
  if (partes.length !== 4) return null;
  let numero = 0;
  for (const parte of partes) {
    if (!/^\d{1,3}$/.test(parte)) return null;
    const valor = Number(parte);
    if (valor > 255) return null;
    numero = numero * 256 + valor;
  }
  return numero;
}

// Faixas IPv4 privadas, locais, reservadas ou de documentação.
const FAIXAS_IPV4_BLOQUEADAS = [
  ['0.0.0.0', 8],       // "esta rede"
  ['10.0.0.0', 8],      // privada
  ['100.64.0.0', 10],   // CGNAT
  ['127.0.0.0', 8],     // loopback
  ['169.254.0.0', 16],  // link-local (inclui metadados de nuvem 169.254.169.254)
  ['172.16.0.0', 12],   // privada (inclui as redes do Docker)
  ['192.0.0.0', 24],    // IETF
  ['192.0.2.0', 24],    // documentação
  ['192.88.99.0', 24],  // 6to4 relay
  ['192.168.0.0', 16],  // privada
  ['198.18.0.0', 15],   // testes de desempenho
  ['198.51.100.0', 24], // documentação
  ['203.0.113.0', 24],  // documentação
  ['224.0.0.0', 4],     // multicast
  ['240.0.0.0', 4],     // reservada e broadcast
];

function ipv4Bloqueado(ip) {
  const numero = ipv4ParaNumero(ip);
  if (numero === null) return true;
  return FAIXAS_IPV4_BLOQUEADAS.some(([base, bits]) => {
    const mascara = bits === 0 ? 0 : (0xffffffff << (32 - bits)) >>> 0;
    return ((numero & mascara) >>> 0) === ((ipv4ParaNumero(base) & mascara) >>> 0);
  });
}

// Expande um IPv6 para 8 grupos numéricos. Devolve null se for inválido.
function expandirIPv6(ip) {
  let texto = String(ip).replace(/^\[|\]$/g, '').toLowerCase();
  const zona = texto.indexOf('%');
  if (zona >= 0) texto = texto.slice(0, zona);
  const comIPv4 = texto.match(/^(.*:)(\d+\.\d+\.\d+\.\d+)$/);
  if (comIPv4) {
    const numero = ipv4ParaNumero(comIPv4[2]);
    if (numero === null) return null;
    texto = comIPv4[1] + (numero >>> 16).toString(16) + ':' + (numero & 0xffff).toString(16);
  }
  const metades = texto.split('::');
  if (metades.length > 2) return null;
  const esquerda = metades[0] ? metades[0].split(':') : [];
  const direita = metades.length === 2 && metades[1] ? metades[1].split(':') : [];
  const faltam = 8 - esquerda.length - direita.length;
  if (metades.length === 1 && faltam !== 0) return null;
  if (metades.length === 2 && faltam < 1) return null;
  const grupos = [...esquerda, ...Array(metades.length === 2 ? faltam : 0).fill('0'), ...direita];
  if (grupos.some((g) => !/^[0-9a-f]{1,4}$/.test(g))) return null;
  return grupos.map((g) => parseInt(g, 16));
}

function ipv6Bloqueado(ip) {
  const g = expandirIPv6(ip);
  if (!g) return true;
  const ipv4Embutido = () => `${g[6] >> 8}.${g[6] & 255}.${g[7] >> 8}.${g[7] & 255}`;
  // IPv4 mapeado (::ffff:a.b.c.d) e NAT64 (64:ff9b::a.b.c.d): vale a regra do IPv4 embutido.
  if (g.slice(0, 5).every((x) => x === 0) && g[5] === 0xffff) return ipv4Bloqueado(ipv4Embutido());
  if (g[0] === 0x64 && g[1] === 0xff9b && g.slice(2, 6).every((x) => x === 0)) return ipv4Bloqueado(ipv4Embutido());
  // Só aceita endereços globais (2000::/3). Isso já exclui ::1, fc00::/7, fe80::/10 e multicast.
  if ((g[0] & 0xe000) !== 0x2000) return true;
  if (g[0] === 0x2001 && (g[1] === 0x0db8 || g[1] === 0)) return true; // documentação e Teredo
  if (g[0] === 0x2002) return true; // 6to4 (embute um IPv4 qualquer)
  return false;
}

function ehIPv4(texto) {
  return ipv4ParaNumero(texto) !== null;
}

function ipBloqueado(ip) {
  return String(ip).includes(':') ? ipv6Bloqueado(ip) : ipv4Bloqueado(ip);
}
// ---- fim da biblioteca ----

// ---- Biblioteca: texto seguro ----
// Tudo o que vem do chamado e do e-mail suspeito foi escrito por um usuário ou por um ATACANTE.
// Por isso: esc() antes de ir para o Telegram/GLPI (vira texto, nunca HTML) e desarmar() nos
// indicadores (hxxps://site[.]com), para o analista não abrir um link malicioso sem querer.

const ENTIDADES = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', ordm: 'º', ordf: 'ª', euro: '€', copy: '©', reg: '®', ndash: '–', mdash: '—', hellip: '…', laquo: '«', raquo: '»' };
// Letras acentuadas do português: &aacute; &Atilde; &ccedil; ...
for (const [letras, acento, base] of [['aeiou', 'acute', 0x301], ['aeiou', 'grave', 0x300], ['aeiou', 'circ', 0x302], ['aon', 'tilde', 0x303], ['aeiou', 'uml', 0x308], ['c', 'cedil', 0x327]]) {
  for (const l of letras) {
    ENTIDADES[l + acento] = (l + String.fromCharCode(base)).normalize('NFC');
    ENTIDADES[l.toUpperCase() + acento] = (l.toUpperCase() + String.fromCharCode(base)).normalize('NFC');
  }
}

function decodificarEntidades(texto) {
  return String(texto ?? '').replace(/&(#x[0-9a-f]{1,6}|#\d{1,7}|[a-z]{2,8});/gi, (inteiro, e) => {
    if (e[0] === '#') {
      const n = e[1].toLowerCase() === 'x' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return n > 0 && n < 0x110000 && !(n >= 0xd800 && n <= 0xdfff) ? String.fromCodePoint(n) : inteiro;
    }
    return ENTIDADES[e] ?? ENTIDADES[e.toLowerCase()] ?? inteiro;
  });
}

// HTML -> texto. O GLPI guarda o conteúdo do chamado com as tags escapadas (&lt;p&gt;): desfaz isso antes.
function htmlParaTexto(html) {
  let s = String(html ?? '');
  if (/&lt;\/?[a-z][\s\S]*?&gt;/i.test(s) && !/<\/?[a-z][^>]*>/i.test(s)) s = decodificarEntidades(s);
  s = s.replace(/<(script|style|head|title)\b[\s\S]*?<\/\1\s*>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|tr|li|h\d|blockquote|table)\s*>/gi, '\n')
    .replace(/<[^>]*>/g, ' ');
  return decodificarEntidades(s)
    .replace(/[ \t ]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// Escapa para HTML do Telegram e do GLPI (o Telegram só reconhece &, < e >; " protege atributos).
function esc(texto) {
  return String(texto ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// Corta o texto e remove caracteres de controle (mantém quebras de linha).
function curto(texto, maximo = 200) {
  const t = String(texto ?? '').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f​-‏‪-‮⁦-⁩]/g, '').trim();
  return t.length > maximo ? t.slice(0, maximo - 1) + '…' : t;
}

// Uma linha só (sem quebras), cortada.
function linha(texto, maximo = 200) {
  return curto(String(texto ?? '').replace(/\s+/g, ' '), maximo);
}

// Indicador "desarmado": https://mal.com/x -> hxxps://mal[.]com/x ; a@mal.com -> a[@]mal[.]com ; 1.2.3.4 -> 1.2.3[.]4
function desarmar(ioc) {
  const texto = String(ioc ?? '');
  const url = texto.match(/^([a-z][a-z0-9+.-]*)(:\/\/)([^/?#]*)(.*)$/i);
  if (url) return url[1].replace(/^http/i, (p) => p[0] + 'xx' + p[3]) + url[2] + url[3].replace(/\./g, '[.]').replace(/@/g, '[@]') + url[4];
  return texto.replace(/@/g, '[@]').replace(/\.(?=[^.]*$)/, '[.]');
}

function unicos(lista, maximo = 50) {
  const vistos = new Set();
  const saida = [];
  for (const item of lista) {
    const chave = String(item).toLowerCase();
    if (!item || vistos.has(chave)) continue;
    vistos.add(chave);
    saida.push(item);
    if (saida.length >= maximo) break;
  }
  return saida;
}
// ---- fim da biblioteca ----

// ---- Biblioteca: leitura de e-mail (.eml / MIME) e de cabeçalhos colados no chamado ----
// Feita à mão (sem bibliotecas externas) porque roda dentro do nó Code do n8n.
// Só LÊ o e-mail: nenhum link é aberto e nenhum anexo é executado.

function bytesDeBase64(texto) {
  const tabela = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const limpo = String(texto ?? '').replace(/[^A-Za-z0-9+/]/g, '');
  const bytes = [];
  for (let i = 0; i + 1 < limpo.length; i += 4) {
    const n = (tabela.indexOf(limpo[i]) << 18) | (tabela.indexOf(limpo[i + 1]) << 12)
      | ((i + 2 < limpo.length ? tabela.indexOf(limpo[i + 2]) : 0) << 6) | (i + 3 < limpo.length ? tabela.indexOf(limpo[i + 3]) : 0);
    bytes.push((n >> 16) & 255);
    if (i + 2 < limpo.length) bytes.push((n >> 8) & 255);
    if (i + 3 < limpo.length) bytes.push(n & 255);
  }
  return bytes;
}

function bytesDeQP(texto) {
  const s = String(texto ?? '').replace(/=\r?\n/g, '');
  const bytes = [];
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '=' && /^[0-9a-f]{2}$/i.test(s.slice(i + 1, i + 3))) {
      bytes.push(parseInt(s.slice(i + 1, i + 3), 16));
      i += 2;
    } else {
      const c = s.charCodeAt(i);
      if (c < 0x80) bytes.push(c);
      else for (const b of unescape(encodeURIComponent(s[i]))) bytes.push(b.charCodeAt(0));
    }
  }
  return bytes;
}

function utf8(bytes) {
  let saida = '';
  for (let i = 0; i < bytes.length; i++) {
    const b = bytes[i];
    let n = 0;
    let codigo = 0;
    if (b < 0x80) { saida += String.fromCharCode(b); continue; }
    if (b >= 0xc2 && b < 0xe0) { n = 1; codigo = b & 0x1f; }
    else if (b >= 0xe0 && b < 0xf0) { n = 2; codigo = b & 0x0f; }
    else if (b >= 0xf0 && b < 0xf5) { n = 3; codigo = b & 0x07; }
    else { saida += '�'; continue; }
    let ok = i + n < bytes.length;
    for (let k = 1; ok && k <= n; k++) {
      if ((bytes[i + k] & 0xc0) !== 0x80) ok = false;
      else codigo = (codigo << 6) | (bytes[i + k] & 0x3f);
    }
    if (!ok || codigo > 0x10ffff) { saida += '�'; continue; }
    saida += String.fromCodePoint(codigo);
    i += n;
  }
  return saida;
}

// windows-1252/iso-8859-1 e outros: aproximação por latin1 (bom o bastante para português).
function decodificarBytes(bytes, charset) {
  const c = String(charset ?? 'utf-8').toLowerCase();
  if (c === 'utf-8' || c === 'utf8' || c === 'us-ascii' || c === 'ascii') return utf8(bytes);
  return bytes.map((b) => String.fromCharCode(b)).join('');
}

// "=?UTF-8?B?...?=" e "=?ISO-8859-1?Q?...?=" (RFC 2047), usados no assunto e no nome do remetente.
function decodificarPalavras(valor) {
  return String(valor ?? '')
    .replace(/(=\?[^?]+\?[bq]\?[^?]*\?=)\s+(?==\?)/gi, '$1')
    .replace(/=\?([^?]+)\?([bq])\?([^?]*)\?=/gi, (inteiro, charset, tipo, dados) => {
      const bytes = tipo.toLowerCase() === 'b' ? bytesDeBase64(dados) : bytesDeQP(dados.replace(/_/g, ' '));
      return decodificarBytes(bytes, charset);
    });
}

// Separa cabeçalhos e corpo; junta as linhas dobradas (que começam com espaço).
function separarCabecalhos(bruto) {
  const texto = String(bruto ?? '').replace(/^﻿/, '');
  const fim = texto.search(/\r?\n\r?\n/);
  const parteCabecalhos = fim >= 0 ? texto.slice(0, fim) : texto;
  const corpo = fim >= 0 ? texto.slice(fim).replace(/^\r?\n\r?\n/, '') : '';
  const cabecalhos = [];
  for (const l of parteCabecalhos.split(/\r?\n/)) {
    if (/^[ \t]/.test(l) && cabecalhos.length) cabecalhos[cabecalhos.length - 1].valor += ' ' + l.trim();
    else {
      const m = l.match(/^([!-9;-~]+):[ \t]*(.*)$/);
      if (m) cabecalhos.push({ nome: m[1].toLowerCase(), valor: m[2] });
    }
  }
  return { cabecalhos, corpo };
}

function cabecalho(lista, nome) {
  return lista.find((c) => c.nome === nome)?.valor ?? '';
}

function cabecalhos(lista, nome) {
  return lista.filter((c) => c.nome === nome).map((c) => c.valor);
}

// Parâmetro de um cabeçalho: boundary, charset, filename (inclusive filename*=utf-8''...).
function parametro(valor, nome) {
  const v = String(valor ?? '');
  const estendido = v.match(new RegExp(`(?:^|;)\\s*${nome}\\*=([^']*)'[^']*'([^;]+)`, 'i'));
  if (estendido) {
    try { return decodeURIComponent(estendido[2].trim()); } catch (erro) { return estendido[2].trim(); }
  }
  const m = v.match(new RegExp(`(?:^|;)\\s*${nome}\\s*=\\s*("([^"]*)"|[^;\\s]+)`, 'i'));
  return m ? decodificarPalavras(m[2] ?? m[1]) : '';
}

// Lê uma mensagem MIME. Devolve cabeçalhos, textos (plain/html), anexos (com os bytes) e
// mensagens encaminhadas como anexo (message/rfc822), cada uma lida do mesmo jeito.
function analisarMime(bruto, profundidade = 0) {
  const { cabecalhos: cabs, corpo } = separarCabecalhos(bruto);
  const resultado = { cabecalhos: cabs, textos: [], anexos: [], internas: [] };
  juntarParte(cabs, corpo, resultado, profundidade);
  return resultado;
}

function juntarParte(cabs, corpo, resultado, profundidade) {
  const tipoCompleto = cabecalho(cabs, 'content-type') || 'text/plain';
  const tipo = tipoCompleto.split(';')[0].trim().toLowerCase();
  const codificacao = cabecalho(cabs, 'content-transfer-encoding').trim().toLowerCase();
  const disposicao = cabecalho(cabs, 'content-disposition');
  const nome = parametro(disposicao, 'filename') || parametro(tipoCompleto, 'name');

  if (tipo.startsWith('multipart/') && profundidade < 6) {
    const fronteira = parametro(tipoCompleto, 'boundary');
    if (!fronteira) return;
    const pedacos = corpo.split('--' + fronteira);
    for (const pedaco of pedacos.slice(1)) {
      if (pedaco.startsWith('--')) break;
      const p = separarCabecalhos(pedaco.replace(/^\r?\n/, ''));
      juntarParte(p.cabecalhos, p.corpo, resultado, profundidade + 1);
    }
    return;
  }

  const bytes = codificacao === 'base64' ? bytesDeBase64(corpo) : codificacao === 'quoted-printable' ? bytesDeQP(corpo) : null;
  const conteudo = () => (bytes ? decodificarBytes(bytes, parametro(tipoCompleto, 'charset')) : corpo);

  if (tipo === 'message/rfc822' && profundidade < 6) {
    resultado.internas.push(analisarMime(conteudo(), profundidade + 1));
    return;
  }
  const ehAnexo = /^\s*attachment/i.test(disposicao) || (nome && !/^text\/(plain|html)$/.test(tipo));
  if (!ehAnexo && (tipo === 'text/plain' || tipo === 'text/html')) {
    resultado.textos.push({ tipo, conteudo: conteudo() });
    return;
  }
  const dados = bytes ?? Array.from(corpo, (c) => c.charCodeAt(0) & 255);
  resultado.anexos.push({ nome: nome || '(sem nome)', tipo, tamanho: dados.length, bytes: dados });
}

// '"Banco" <a@b.com>' -> { nome: 'Banco', email: 'a@b.com', dominio: 'b.com' }
// O endereço real é o ÚLTIMO <...>: '"Banco <a@banco.com>" <golpe@falso.com>' é golpe@falso.com.
function endereco(valor) {
  const v = decodificarPalavras(valor).trim();
  const ultimo = v.lastIndexOf('<');
  const m = ultimo >= 0 ? v.slice(ultimo).match(/^<\s*([^>\s]+@[^>\s]+)\s*>/) : null;
  const email = (m ? m[1] : (v.match(/[^\s<>"',;]+@[^\s<>"',;]+/) ?? [''])[0]).toLowerCase().replace(/^mailto:/, '');
  const nome = m ? v.slice(0, ultimo).trim().replace(/^"|"$/g, '').trim() : '';
  return { nome, email, dominio: email.includes('@') ? email.split('@').pop().replace(/[>.]+$/, '') : '' };
}

// Resultado de SPF/DKIM/DMARC. Só vale o Authentication-Results MAIS DE CIMA (escrito pelo servidor
// que recebeu o e-mail): os de baixo podem ter sido forjados pelo próprio remetente.
function autenticacao(cabs) {
  const ar = cabecalhos(cabs, 'authentication-results')[0] ?? cabecalhos(cabs, 'arc-authentication-results')[0] ?? '';
  const pega = (nome) => (ar.match(new RegExp(`\\b${nome}=([a-z]+)`, 'i'))?.[1] ?? '').toLowerCase();
  const spfCab = (cabecalhos(cabs, 'received-spf')[0] ?? '').match(/^\s*([a-z]+)/i)?.[1]?.toLowerCase() ?? '';
  return { spf: pega('spf') || spfCab, dkim: pega('dkim'), dmarc: pega('dmarc'), presente: Boolean(ar || spfCab) };
}

// IPs públicos que aparecem nos cabeçalhos Received (de baixo para cima = do remetente para nós).
function ipsDosRecebidos(cabs) {
  const ips = [];
  for (const r of cabecalhos(cabs, 'received').reverse()) {
    for (const m of r.matchAll(/\[?\b(\d{1,3}(?:\.\d{1,3}){3})\b\]?/g)) {
      if (!ipBloqueado(m[1]) && !ips.includes(m[1])) ips.push(m[1]);
    }
  }
  return ips;
}

// O usuário colou os cabeçalhos completos no chamado? Procura o primeiro cabeçalho técnico e lê dali.
function cabecalhosColados(texto) {
  const t = String(texto ?? '');
  const inicio = t.search(/^(Received|Return-Path|Delivered-To|Authentication-Results|ARC-Seal|DKIM-Signature|Received-SPF|X-Received):/im);
  if (inicio < 0) return [];
  return separarCabecalhos(t.slice(inicio).replace(/\n\s*\n/g, '\n')).cabecalhos;
}

// Encaminhamento colado (Outlook em português ou inglês): "De: ... Enviado em: ... Assunto: ..."
function encaminhamentoColado(texto) {
  const t = String(texto ?? '');
  const pega = (rotulos) => t.match(new RegExp(`^\\s*(?:\\*\\s*)?(?:${rotulos})\\s*:\\s*(.+)$`, 'im'))?.[1]?.trim() ?? '';
  return {
    de: pega('De|From|Remetente'),
    responder: pega('Responder a|Responder para|Reply-To'),
    assunto: pega('Assunto|Subject'),
    data: pega('Enviado em|Enviada em|Enviado|Data|Date|Sent'),
  };
}
